\[
\begin{align*}
\frac{3}{10} &= \frac{3 \times 21}{10 \times 21} = \frac{63}{210} \\
\frac{1}{3} &= \frac{1 \times 70}{3 \times 70} = \frac{70}{210} \\
\frac{2}{7} &= \frac{2 \times 30}{7 \times 30} = \frac{60}{210}
\end{align*}
\]

